# Builders for the wire format of the v1 business commands, so tests spell out
# the same JSON a phone would send (string keys, UUIDs generated by the caller).
module SyncCommandBuilders
  def uuid = SecureRandom.uuid

  # items: [[public_id, name], ...] or hashes with "public_id", "name", "revives".
  def add_items_command(*items, id: uuid, depends_on: nil, **extra)
    items = items.map { |item| item.is_a?(Array) ? { "public_id" => item[0], "name" => item[1] } : item }
    { "id" => id, "type" => "add_items", "depends_on" => depends_on, "payload" => { "items" => items } }.merge(extra.stringify_keys)
  end

  def set_item_state_command(public_id, desired, lock_version: nil, id: uuid, depends_on: nil)
    command = { "id" => id, "type" => "set_item_state", "depends_on" => depends_on,
      "payload" => { "public_id" => public_id, "desired" => desired } }
    command["preconditions"] = { "lock_version" => lock_version } if lock_version
    command
  end
end
